def run(arguments: dict) -> dict:
    raw_items = arguments.get("items", [])
    if not isinstance(raw_items, list):
        raise ValueError("'items' must be a list of strings.")

    case_sensitive = arguments.get("case_sensitive", True)
    if not isinstance(case_sensitive, bool):
        raise ValueError("'case_sensitive' must be a boolean.")

    seen = set()
    result = []

    for item in raw_items:
        if not isinstance(item, str):
            raise ValueError(f"All elements in 'items' must be strings. Found {type(item).__name__}.")

        key = item if case_sensitive else item.lower()
        if key not in seen:
            seen.add(key)
            result.append(item)

    return {
        "items": result,
        "original_count": len(raw_items),
        "deduped_count": len(result),
        "removed_count": len(raw_items) - len(result)
    }

def run(arguments: dict) -> dict:
    items = arguments.get("items", [])
    if not isinstance(items, list):
        raise ValueError("Parameter 'items' must be a list.")

    seen = set()
    result = []
    for idx, item in enumerate(items):
        if not isinstance(item, str):
            raise ValueError(f"All elements in 'items' must be strings. Element at index {idx} is {type(item).__name__}.")
        if item not in seen:
            seen.add(item)
            result.append(item)

    return {
        "result": result,
        "count": len(result),
        "duplicates_removed": len(items) - len(result)
    }

def run(arguments: dict) -> dict:
    if not isinstance(arguments, dict):
        raise ValueError("Arguments must be a dictionary.")

    if "celsius" not in arguments:
        raise ValueError("Missing required argument: 'celsius'.")

    celsius = arguments["celsius"]
    if isinstance(celsius, bool) or not isinstance(celsius, (int, float)):
        raise ValueError("The 'celsius' argument must be a valid number.")

    # Convert Celsius to Fahrenheit: F = C * 9/5 + 32
    fahrenheit = float(celsius) * 9.0 / 5.0 + 32.0
    fahrenheit = round(fahrenheit, 10)

    return {
        "celsius": float(celsius),
        "fahrenheit": fahrenheit
    }

